#ifndef MODULES_INTERFACE_HPP
#define MODULES_INTERFACE_HPP

// C-callable entry points provided by Modules_Interface.cpp.
// Called by CXX_Interface to initialise and finalise all Fortran module
// pointer associations during the Fortran/C++ mixed-language transitional phase.
extern "C" {
  void modules_fi_init_();
  void modules_fi_finalize_();
}

#endif

/*
 * C++ translation of Modules_Interface.f90
 *
 * Provides the C-callable symbols modules_fi_init_() and
 * modules_fi_finalize_() that CXX_Interface calls at construction /
 * destruction time.  The actual work — establishing c_f_pointer
 * associations inside each Fortran module shim — must be done on the
 * Fortran side because the shim init/finalize routines are plain Fortran
 * module procedures without bind(C).  The Fortran shim
 * Modules_Interface_fi.F90 exports them under the renamed bind(C) symbols
 * modules_fi_init_fshim_ / modules_fi_finalize_fshim_ to avoid a
 * duplicate-symbol conflict with the definitions here.
 *
 * TODO: Remove together with Modules_Interface_fi.F90 once all Fortran
 * module shims are retired and no Fortran pointer associations remain.
 */

#include <Modules_Interface.hpp>

// Declarations for the Fortran shim entry points
extern "C" {
  void modules_fi_init_fshim_();
  void modules_fi_finalize_fshim_();
}

extern "C" {
  void modules_fi_init_() { // @coverage-probe
    modules_fi_init_fshim_();
  }

  void modules_fi_finalize_() {
    modules_fi_finalize_fshim_();
  }
}
